public:
    int maxProduct(vector<int>& nums) {
        int n = nums.size();
        int result = nums[0];

        int curMax = 1;
        int curMin = 1;

        for(int i = 0; i < n; i++){
            if(nums[i] == 0){
                result = max(result, 0);

                curMax = 1;
                curMin= 1;
                continue;
            }
            int prevMax = curMax;
            int prevMin = curMin;

            curMax = max({nums[i], prevMax * nums[i], prevMin*nums[i]});

            curMin = min({nums[i], prevMax * nums[i], prevMin*nums[i]});

            result = max(curMax, result);

        }

        return result;
    }
};
```

